    always @* begin : p_l562 integer li, lj, lk;
        ll_tk = {NLL{1'b0}}; lsel_v = {NLP{1'b0}};
        for (lk = 0; lk < NLP; lk = lk + 1) lsel[lk] = {$clog2(NLL){1'b0}};
        lk = 0;
        // lanes with no back-pressure first (rotating), the collective's flow-controlled word lanes take what is left
        for (li = 0; li < NLL; li = li + 1) begin
            lj = (ll_ptr + li) % NLL;
            if (lc[lj] != 7'd0 && lk < NLP && !(lj >= 2 * NSVC && lj < 2 * NSVC + 4)) begin
                ll_tk[lj] = 1'b1; lsel_v[lk] = 1'b1; lsel[lk] = lj; lk = lk + 1;
            end
        end
        for (li = 0; li < 4; li = li + 1) begin
            lj = 2 * NSVC + li;
            if (lc[lj] != 7'd0 && lk < NLP) begin ll_tk[lj] = 1'b1; lsel_v[lk] = 1'b1; lsel[lk] = lj; lk = lk + 1; end
        end
    end
`endif
    reg [NLL-1:0] sd_oh [0:NLP-1][0:LSD-1]; reg [NLP-1:0] sd_v [0:LSD-1];
    always @(posedge clk) begin : p_l578 integer lk, li, i; reg [511:0] dsel; reg [13:0] rsel;
        if (!rn) begin
            lp_v <= {NLP{1'b0}}; ll_ptr <= 0; av_r <= {NLL{1'b0}};
            for (li = 0; li < NLL; li = li + 1) lc[li] <= 7'd0;
            for (i = 0; i < LGL; i = i + 1) g_r[i] <= {NLL{1'b0}};
            for (i = 0; i < LSD; i = i + 1) sd_v[i] <= {NLP{1'b0}};
        end else begin
            ll_ptr <= (ll_ptr == NLL - 1) ? 0 : ll_ptr + 1'b1;
            av_r <= ll_avd;
            for (li = 0; li < NLL; li = li + 1) lc[li] <= lc[li] + {6'd0, av_r[li]} - {6'd0, ll_tk[li]};
            g_r[0] <= ll_tk;
            for (i = 1; i < LGL; i = i + 1) g_r[i] <= g_r[i-1];
            sd_v[0] <= lsel_v;
            for (i = 1; i < LSD; i = i + 1) sd_v[i] <= sd_v[i-1];
            lp_v <= sd_v[LSD-1];
        end
        for (lk = 0; lk < NLP; lk = lk + 1) begin
            sd_oh[lk][0] <= lsel_v[lk] ? ({{(NLL-1){1'b0}}, 1'b1} << lsel[lk]) : {NLL{1'b0}};
            for (i = 1; i < LSD; i = i + 1) sd_oh[lk][i] <= sd_oh[lk][i-1];
            dsel = 512'd0; rsel = 14'd0;
            for (li = 0; li < NLL; li = li + 1) if (sd_oh[lk][LSD-1][li]) begin
                dsel = dsel | dd_r[LDL-1][512*li +: 512]; rsel = rsel | dr_r[LDL-1][14*li +: 14];
            end
            lp_row[14*lk +: 14] <= rsel; lp_d[512*lk +: 512] <= dsel;
        end
        dd_r[0] <= ll_od; dr_r[0] <= ll_or;
        for (i = 1; i < LDL; i = i + 1) begin dd_r[i] <= dd_r[i-1]; dr_r[i] <= dr_r[i-1]; end
    end
    // ---- end verbatim
    assign g = g_r[0];
    reg [3:0] ok_q; reg [9:0] ov_q, sf_q;
    always @(posedge clk) begin
        if (!rn) begin ok_q <= 4'd0; t_cts <= 3'd0; ovr_o <= 1'b0; sflt_o <= 1'b0; end
        else begin ok_q <= ok; t_cts <= {1'b0, 1'b1, &ok_q}; ovr_o <= |ov_q; sflt_o <= |sf_q; end
        ov_q <= ovf; sf_q <= sflt;
    end
    genvar gj, gs;
    generate for (gj = 0; gj < 2; gj = gj + 1) begin : g_p
        wire [571:0] fs;
        dsfd_vm_fob #(.WEV(0)) u_b (.clk(clk), .rn(rn), .i_v(lp_v[gj]), .i_we(1'b1), .i_row(lp_row[14*gj +: 14]), .i_m(16'hffff),
            .i_d(lp_d[512*gj +: 512]), .s_o(fs), .x_o(), .k_o(k_o[32*gj +: 32]));
        for (gs = 0; gs < 4; gs = gs + 1) begin : g_s
            assign s_o[(2*gs + gj)*143 +: 143] = fs[143*gs +: 143];
        end
    end endgenerate
`ifdef OT_SPVM_RESET_ACK
    dsfd_vm_reset_ack #(.N(1)) u_reset_ack (.clk(clk), .request_n(reset_epoch_n), .local_release(rn), .consumer_live(1'b1), .ack(rst_ack));
`endif
endmodule

// ================================================================ fcc: ctrl VM port CDC (ports 3 / 4)
(* keep_hierarchy = "yes" *)
module dsfd_vm_fcc (
    input  wire [0:0]    ck, input wire rni,
    input  wire [0:0]    cks, input wire [0:0] rss,
    input  wire [0:0]    rst,           // B8: asynchronous serial reset, ONLY into the crossing's two reset synchronisers (rst & rss)
    input  wire [0:0]    vwe, input wire [13:0] vwa, input wire [511:0] vwd,
    input  wire [0:0]    vre, input wire [13:0] vra,
    output wire [1151:0] s_o,           // slice s, port 3 + j at [(2*s + j)*144 +: 144] = {v, we, row 14, d 128}
    output wire [63:0]   k_o,
    output wire          so_o,
    output reg  [1:0]    rn_o
`ifdef OT_SPVM_RESET_ACK
    , output wire [1:0] rst_ack, output wire [1:0] rst_ack_s
`endif
);
    localparam integer CCA = `VMFE_CCA;
    // This CLOSED ctrl leaf retains its legacy full-row interface. True commit
    // metadata uses a separately qualified native variant, never these constants.
    localparam integer WCOMMIT=0;
    wire [15:0] vwm=16'hffff; wire [7:0] vwt=8'd0; wire vready;
    wire clk = ck[0];
    reg rn; wire rns;
    (* keep = 1 *) reg [1:0] rn_k;
    always @(posedge clk) begin rn <= rni; rn_k <= {2{rn}}; end
    always @* rn_o = rn_k;
    ot_dsrom_mtp_rstsync u_rss (.clk(cks[0]), .rst_n_async(rss[0]), .rst_n(rns));
    // ---- verbatim from the flat dsfd_vm_fe
    // ---------------------------------------------------------------- ctrl VM port: stream pins -> 2 ratio CDC FIFOs
    reg [15:0] s_wm; reg [7:0] s_wt;
    reg s_we, s_re, s_tg; reg [13:0] s_wa, s_ra; reg [511:0] s_wd;
    always @(posedge cks[0]) begin
        if (!rns) begin s_we <= 1'b0; s_re <= 1'b0; end else begin s_we <= vwe[0]; s_re <= vre[0]; end
        s_wm <= WCOMMIT ? vwm : 16'hffff; s_wt <= WCOMMIT ? vwt : 8'd0;
        s_wa <= vwa; s_ra <= vra; s_wd <= vwd;
    end
    // up to two ops a stream cycle (a write and a read: the write is ordered first).  Ops alternate between the two
    // FIFOs (s_tg = the FIFO of the next op); the serial side drains <= 2 a cycle, so the controller's VM op rate must
    // stay <= 1.5 a stream cycle on average (8-entry FIFOs); beyond -> sticky overflow fault (fail closed).
    wire [550:0] s_wo = {s_wt,s_wm,1'b1, s_wa, s_wd}, s_ro = {24'd0,1'b0, s_ra, 512'd0};   // {we, row, data}
    wire s_f = s_we | s_re;                       // first op of the cycle
    wire s_s = s_we & s_re;                       // second op (the read)
    wire [550:0] s_fd = s_we ? s_wo : s_ro;
    wire [1:0] sw_v = {(s_f && s_tg) || (s_s && !s_tg), (s_f && !s_tg) || (s_s && s_tg)};
    wire [550:0] sw_d0 = (s_f && !s_tg) ? s_fd : s_ro;
    wire [550:0] sw_d1 = (s_f && s_tg) ? s_fd : s_ro;
    always @(posedge cks[0]) if (!rns) s_tg <= 1'b0; else if (s_f && !s_s) s_tg <= ~s_tg;
    `ifdef OT_SPVM_RESET_ACK
    wire [1:0] fifo_live_w, fifo_live_r;
`endif
    wire [1:0] cw_rdy, cr_v, cw_live; wire [550:0] cr_d0, cr_d1; reg [1:0] cr_take; reg s_ovf;
    generate if (CCA != 0) begin : g_cca
        // el1013-s81-vmfe/B8 (coordinator decision 10-13 (b)): with ot_ratio_cdc_fifo every storage bit crossed EVERY read
        // cycle (mem[i] (cks tree) -> sh[i] (ck tree), 2 x 8 x 527 flop -> flop arcs) and had to meet the 277.8-ps window AND
        // the coincident-edge hold between two independently built clock trees: -140.7 ps setup, 2,039 stalled hold arcs.
        // Here the storage is written and held in the stream domain only (its write register s_wd / s_wa is same-domain),
        // the pointers cross Gray-coded through 2-flop synchronisers, and an entry is read (mem -> read mux -> the serial
        // order register) only after the synchronised pointer has published it, >= 2 serial cycles after it was written:
        // the only cross-clock arcs are pointer / online -> first synchroniser flop and stable storage -> order register
        // (max-delay, datapath only).  Reset: one synchroniser a domain on the pin-level AND of both asynchronous resets
        // (an assertion of either flushes both sides), then one registered stage; no cross-domain reset arc.
        wire x_arn = rst[0] & rss[0];
        wire xw0, xr0; wire [1:0] xr_v;
        ot_reset_sync u_xw (.clk(cks[0]), .async_rst_n(x_arn), .sync_rst_n(xw0));
        ot_reset_sync u_xr (.clk(clk), .async_rst_n(x_arn), .sync_rst_n(xr0));
        (* keep = 1 *) reg [1:0] xw_t; (* keep = 1 *) reg [1:0] xr_t;
        always @(posedge cks[0] or negedge xw0) if (!xw0) xw_t <= 2'b00; else xw_t <= 2'b11;
        always @(posedge clk or negedge xr0) if (!xr0) xr_t <= 2'b00; else xr_t <= 2'b11;
        ot_async_fifo #(.WIDTH(551), .DEPTH(16), .EXT_RST(1)
`ifdef OT_VMFE_FCC_PIPE
            , .FIFO_PIPE(1)
`endif
            ) u_cc0 (.wr_clk(cks[0]), .wr_rst_n(xw_t[0]), .wr_valid(sw_v[0]),
            .wr_ready(cw_rdy[0]), .wr_data(sw_d0), .wr_overflow(), .rd_clk(clk), .rd_rst_n(xr_t[0]), .rd_valid(xr_v[0]),
            .rd_ready(cr_take[0]), .rd_data(cr_d0), .rd_underflow()
`ifdef OT_SPVM_RESET_ACK
            , .wr_reset_live(fifo_live_w[0]), .rd_reset_live(fifo_live_r[0])
`endif
            );
        ot_async_fifo #(.WIDTH(551), .DEPTH(16), .EXT_RST(1)
`ifdef OT_VMFE_FCC_PIPE
            , .FIFO_PIPE(1)
`endif
            ) u_cc1 (.wr_clk(cks[0]), .wr_rst_n(xw_t[1]), .wr_valid(sw_v[1]),
            .wr_ready(cw_rdy[1]), .wr_data(sw_d1), .wr_overflow(), .rd_clk(clk), .rd_rst_n(xr_t[1]), .rd_valid(xr_v[1]),
            .rd_ready(cr_take[1]), .rd_data(cr_d1), .rd_underflow()
`ifdef OT_SPVM_RESET_ACK
            , .wr_reset_live(fifo_live_w[1]), .rd_reset_live(fifo_live_r[1])
`endif
            );
        assign cr_v = rn ? xr_v : 2'b00;        // nothing is popped while the serial order registers are in reset
        assign cw_live = 2'b11;
`ifdef OT_SPVM_RESET_ACK
    dsfd_vm_reset_ack #(.N(2)) u_cross_ack_r (.clk(clk), .request_n(x_arn), .local_release(xr_t), .consumer_live(&fifo_live_r), .ack(rst_ack[1]));
    dsfd_vm_reset_ack #(.N(2)) u_cross_ack_w (.clk(cks[0]), .request_n(x_arn), .local_release(xw_t), .consumer_live(&fifo_live_w), .ack(rst_ack_s[1]));
`endif
    end else begin : g_ncca
`ifdef OT_SPVM_RESET_ACK
        assign fifo_live_w = cw_live;
    dsfd_vm_reset_ack #(.N(1)) u_cross_ack_r (.clk(clk), .request_n(rst[0]), .local_release(rn), .consumer_live(&fifo_live_r), .ack(rst_ack[1]));
    dsfd_vm_reset_ack #(.N(1)) u_cross_ack_w (.clk(cks[0]), .request_n(rss[0]), .local_release(rns), .consumer_live(&fifo_live_w), .ack(rst_ack_s[1]));
`endif
        ot_ratio_cdc_fifo #(.W(551), .DEPTH(8)) u_cc0 (.wclk(cks[0]), .wrst_n(rns), .w_v(sw_v[0]), .w_rdy(cw_rdy[0]), .w_d(sw_d0),
            .rclk(clk), .rrst_n(rn), .r_v(cr_v[0]), .r_rdy(cr_take[0]), .r_d(cr_d0), .w_live(cw_live[0]), .r_live(
`ifdef OT_SPVM_RESET_ACK
            fifo_live_r[0]
`endif
            ));
        ot_ratio_cdc_fifo #(.W(551), .DEPTH(8)) u_cc1 (.wclk(cks[0]), .wrst_n(rns), .w_v(sw_v[1]), .w_rdy(cw_rdy[1]), .w_d(sw_d1),
            .rclk(clk), .rrst_n(rn), .r_v(cr_v[1]), .r_rdy(cr_take[1]), .r_d(cr_d1), .w_live(cw_live[1]), .r_live(
`ifdef OT_SPVM_RESET_ACK
            fifo_live_r[1]
`endif
            ));
    end endgenerate
    // One request can enter only with both pin stages empty. No intervening
    // writer can consume the selected FIFO slot before this request reaches it.
    assign vready = rns && !vwe[0] && !vre[0] && !s_we && !s_re && cw_rdy[s_tg];
    always @(posedge cks[0]) if (!rns) s_ovf <= 1'b0;
        else if ((sw_v[0] && !cw_rdy[0]) || (sw_v[1] && !cw_rdy[1])) s_ovf <= 1'b1;   // incl. ops before the crossing is up
    // serial side: pop in alternation order, <= 2 a cycle: first -> lane A (p3), second -> lane B (p4)
    reg c_nx;                           // FIFO holding the next op
    reg ca_v, cb_v; reg [550:0] ca_d, cb_d;
    always @* begin
        cr_take = 2'b00;
        if (cr_v[c_nx]) begin
            cr_take[c_nx] = 1'b1;
            if (cr_v[~c_nx]) cr_take[~c_nx] = 1'b1;
        end
    end
    always @(posedge clk) begin
        if (!rn) c_nx <= 1'b0; else if (cr_take == 2'b01 || cr_take == 2'b10) c_nx <= ~c_nx;
    end
    always @* begin
        ca_v = cr_v[c_nx]; ca_d = c_nx ? cr_d1 : cr_d0;
        cb_v = cr_v[c_nx] && cr_v[~c_nx]; cb_d = c_nx ? cr_d0 : cr_d1;
    end
    // crossing faults (stream side) to the serial domain: sticky, two flops
    reg [1:0] so_s;
    always @(posedge clk) begin so_s <= {so_s[0], s_ovf}; end

    // ---- end verbatim
    assign so_o = so_s[1];
    wire [575:0] fs0, fs1;
`ifdef OT_SPVM_MUT_STALE
    dsfd_vm_fob #(.STALE(1)) u_b3 (
`else
    dsfd_vm_fob u_b3 (
`endif
        .clk(clk), .rn(rn), .i_v(ca_v), .i_we(ca_d[526]), .i_row(ca_d[525:512]), .i_m(16'hffff), .i_d(ca_d[511:0]),
        .s_o(fs0), .x_o(), .k_o(k_o[31:0]));
    dsfd_vm_fob u_b4 (.clk(clk), .rn(rn), .i_v(cb_v), .i_we(cb_d[526]), .i_row(cb_d[525:512]), .i_m(16'hffff),
        .i_d(cb_d[511:0]), .s_o(fs1), .x_o(), .k_o(k_o[63:32]));
    genvar gs;
    generate for (gs = 0; gs < 4; gs = gs + 1) begin : g_s
        assign s_o[(2*gs)*144 +: 144] = fs0[144*gs +: 144]; assign s_o[(2*gs + 1)*144 +: 144] = fs1[144*gs +: 144];
    end endgenerate
`ifdef OT_SPVM_RESET_ACK
    dsfd_vm_reset_ack #(.N(1)) u_reset_ack (.clk(clk), .request_n(rst[0]), .local_release(rn), .consumer_live(1'b1), .ack(rst_ack[0]));
    dsfd_vm_reset_ack #(.N(1)) u_stream_ack (.clk(cks[0]), .request_n(rss[0]), .local_release(rns), .consumer_live(1'b1), .ack(rst_ack_s[0]));
`endif
endmodule

// ================================================================ fcw: WFC kit endpoint (ports 0 / 1)
(* keep_hierarchy = "yes" *)
module dsfd_vm_fcw (
    input  wire [0:0]    ck, input wire rni, input wire [0:0] rst,
    input  wire [0:0]    f_swv, input wire [526:0] f_swd, output wire [0:0] t_swg,
    input  wire [0:0]    f_srv, input wire [30:0]  f_srd, output wire [0:0] t_srg,
    output wire [52:0]   t_ks,
    output wire [635:0]  s_o,           // slice s at [159*s +: 159] = {port 1 {v, row 14}, port 0 {v, we, row 14, d 128}}
    output wire [63:0]   k_o,
    output reg           err_o,         // sticky: kit error | read of a row >= 2^14
    output reg  [1:0]    rn_o
`ifdef OT_SPVM_RESET_ACK
    , output wire [1:0] rst_ack
`endif
);
    wire clk = ck[0];
    reg rn;
    (* keep = 1 *) reg [1:0] rn_k;
    always @(posedge clk) begin rn <= rni; rn_k <= {2{rn}}; end
    always @* rn_o = rn_k;
    wire e_v, e_we, e1_v, e_err; wire [14:0] e_row, e1_row; wire [511:0] e_d;
    // WNQ 1: the write receiver without its 30 x 527 slots (dead storage in the flat module: the endpoint's write
    // consumer is tied ready, so no flit is ever queued; the flat reference keeps them and lockstep proves equality)
    dsfd_vm_wfc_ep #(.FLIT(512), .NW(21), .USER_W(10), .VWA(15), .VF(13), .VR(13), .PIPE(2), .RD2(1), .WNQ(1)) u_wfc (
        .ck(ck), .rst(rst),
        .f_swv(f_swv), .f_swd(f_swd), .t_swg(t_swg), .f_srv(f_srv), .f_srd(f_srd), .t_srg(t_srg),
        .t_srq(), .t_err(e_err), .t_ks(t_ks),
        .m_v(e_v), .m_we(e_we), .m_row(e_row), .m_d(e_d), .m_ov(1'b0), .m_od(512'd0), .m_fault(1'b0),
        .m1_v(e1_v), .m1_row(e1_row), .m1_ov(1'b0), .m1_od(512'd0)
`ifdef OT_SPVM_RESET_ACK
        , .rst_ack(rst_ack[1])
`endif
        );
    always @(posedge clk) if (!rn) err_o <= 1'b0; else if (e_err || (e_v && e_row[14]) || (e1_v && e1_row[14])) err_o <= 1'b1;
    wire [575:0] fs0; wire [59:0] fs1;
    dsfd_vm_fob u_b0 (.clk(clk), .rn(rn), .i_v(e_v && !e_row[14]), .i_we(e_we), .i_row(e_row[13:0]), .i_m(16'hffff),
        .i_d(e_d), .s_o(fs0), .x_o(), .k_o(k_o[31:0]));
    dsfd_vm_fob #(.WEV(0), .DF(0)) u_b1 (.clk(clk), .rn(rn), .i_v(e1_v && !e1_row[14]), .i_we(1'b0), .i_row(e1_row[13:0]),
        .i_m(16'hffff), .i_d(512'd0), .s_o(fs1), .x_o(), .k_o(k_o[63:32]));
    genvar gs;
    generate for (gs = 0; gs < 4; gs = gs + 1) begin : g_s
        assign s_o[159*gs +: 159] = {fs1[15*gs +: 15], fs0[144*gs +: 144]};
    end endgenerate
`ifdef OT_SPVM_RESET_ACK
    dsfd_vm_reset_ack #(.N(1)) u_reset_ack (.clk(clk), .request_n(rst[0]), .local_release(rn), .consumer_live(1'b1), .ack(rst_ack[0]));
`endif
endmodule

// ================================================================ fcn: control (adapter, P2RD, X streamers, counter)
// own ports 2, 5, 6, 7, 8, 9 (s_o slot j = 0 .. 5).  k_i = the k copies of the 22 other ports, ascending
// (0, 1, 3, 4, 10, 11, 12 .. 27); the kq register here is the in-pin flop = the flat kq[KD-1].
(* keep_hierarchy = "yes" *)
module dsfd_vm_fcn (
    input  wire [0:0]    ck, input wire [0:0] rst, input wire [0:0] cks, input wire [0:0] rss,
    input  wire [0:0]    cv, input wire [83:0] cd, output wire [0:0] dv, output wire [7:0] dt,
    input  wire [63:0]   f_cq, input wire [0:0] f_p2c,
    output reg  [0:0]    c_wv, output reg [9:0] c_wd, input wire [0:0] c_wr,
    output reg  [3:0]    t_rdy,
    input  wire [703:0]  k_i,
    input  wire [15:0]   clf_i, input wire so_i, input wire ovr_i, input wire sflt_i, input wire err_i,
    output wire [359:0]  s_o,           // slice s, own slot j at [(6*s + j)*15 +: 15] = {v, row 14}
    output wire [111:0]  x_o,           // slice-0 data tags: {p9 4, p8 4, p7 4, p6 4, p5 92, p2 4}
    output reg  [9:0]    arm_v, output reg [139:0] arm_base,
    output reg  [3:0]    rf_o,
    output reg  [15:0]   fe_flt,
    output reg  [7:0]    rn_o
`ifdef OT_SPVM_RESET_ACK
    , output wire [1:0] rst_ack, output wire [1:0] rst_ack_s
`endif
);
    localparam integer NP = 28, RA = 14, NSLOT = 4, P2D = 40, CQD = 4, KD = 1, DVR = `VMFE_DVR, XRT = `VMFE_XRT;
    wire clk = ck[0];
    wire rn0, rns;
    ot_dsrom_mtp_rstsync u_rs (.clk(clk), .rst_n_async(rst[0]), .rst_n(rn0));
    (* keep = 1 *) reg [1:0] rr_c;
    (* keep = 1 *) reg [7:0] rn_k;
    always @(posedge clk) begin rr_c <= {rr_c[0], rn0}; rn_k <= {8{rn0}}; end
    always @* rn_o = rn_k;
    wire rn = rr_c[1];
    ot_dsrom_mtp_rstsync u_rss (.clk(cks[0]), .rst_n_async(rss[0]), .rst_n(rns));
    reg [63:0] cq_p;
    always @(posedge clk) cq_p <= f_cq;
    wire cap_src_flt = cq_p[3];
    reg a_p2c;
    always @(posedge clk) if (!rn) a_p2c <= 1'b0; else a_p2c <= f_p2c[0];
    // ---- verbatim from the flat dsfd_vm_fe
    // ---------------------------------------------------------------- engine adapter (stream c side, serial e side)
    wire ad_v, ad_r; wire [83:0] ad_d; wire ad_flt_c, ad_on; wire ad_flt;
    // XRT 1 (B8): the adapter's fault is a STREAM-domain level (cf || ef_c2) read by the serial fault register: it crosses
    // through a stream register and a 2-flop synchroniser (sticky, so +3 cycles on a fault that is already fatal)
    generate if (XRT != 0) begin : g_afs
        reg ad_flt_q; (* async_reg = "true" *) reg [1:0] ad_flt_s;
        always @(posedge cks[0]) ad_flt_q <= ad_flt_c;
        always @(posedge clk) ad_flt_s <= {ad_flt_s[0], ad_flt_q};
        assign ad_flt = ad_flt_s[1];
    end else begin : g_nafs
        assign ad_flt = ad_flt_c;
    end endgenerate
    reg ed_v; reg [7:0] ed_t;
    // engine command pin flops (el1011-ds-vm/fe6): cv / cd enter a register at the pin (stream domain, +1 stream cycle on
    // every command alike) so the adapter's tag lookup (cd -> cpending[tag] -> admit -> u_cmd, 14 levels) starts at a flop
    reg cv_p; reg [83:0] cd_p;
    always @(posedge cks[0]) begin if (!rns) cv_p <= 1'b0; else cv_p <= cv[0]; cd_p <= cd; end
    // engine done pin flops (el1013-s81-vmfe/B6, DVR 1 = the hard leaf dsfd_vm_fcn): the adapter's done register sits in its
    // tag logic (enable, asynchronous clear, 280-load reset), not at the face; dv / dt leave their own stream-domain register
    wire ad_dv; wire [7:0] ad_dt;
    generate if (DVR != 0) begin : g_dvr
        reg dv_q; reg [7:0] dt_q;
        always @(posedge cks[0]) begin if (!rns) dv_q <= 1'b0; else dv_q <= ad_dv; dt_q <= ad_dt; end
        assign dv[0] = dv_q; assign dt = dt_q;
    end else begin : g_ndvr
        assign dv[0] = ad_dv; assign dt = ad_dt;
    end endgenerate
    ot_s81_engine_adapter #(.QD(8), .XRT(XRT)) u_ad (
        .c_clk(cks[0]), .c_rst_n(rss[0]), .c_cmd_v(cv_p), .c_cmd_d(cd_p), .c_done_v(ad_dv), .c_done_tag(ad_dt),
        .fault(ad_flt_c), .online(ad_on),
`ifdef OT_SPVM_RESET_ACK
        .rst_ack_c(rst_ack_s[1]), .rst_ack_e(rst_ack[1]),
`endif
        .e_clk(clk), .e_rst_n(rst[0]), .e_cmd_v(ad_v), .e_cmd_d(ad_d), .e_cmd_ready(ad_r), .e_inputs_present(1'b1),
        .e_done_v(ed_v), .e_done_tag(ed_t));
    wire [2:0] vop = ad_d[30:28];       // arg[23:21]
    wire [23:0] arg = ad_d[30:7];
    wire [7:0] ctag = {ad_d[83], ad_d[6:0]};
    reg imm_v; reg [7:0] imm_t;         // one immediate done waiting for the done output
    reg [$clog2(CQD+1)-1:0] cq_n;
    wire [2:0] xp_c = arg[20:18];        // X op: streamer index
    wire x_go = arg[17];
    reg [4:0] x_act;
`ifdef OT_SPVM_XGOS
    // XGOS (claude s81-grpA r3, default-off VM-read variant): XGO arg[16] = wait, arg[15:14] = producer slot.  The
    // streamer is loaded at once but starts only when the slot COMPLETES (or at once if the slot completed and was not
    // re-armed since): the controller no longer waits for the producer's ARMN done to issue the consumer's XGO.
    reg [4:0] x_wt, x_rel;              // waiting on a slot / release pulse (row-completion counter section)
    wire x_hold_new = vop == 3'd7 && x_go && xp_c < 3'd5 && (x_wt[xp_c] || x_rel[xp_c]);
`else
    wire x_hold_new = 1'b0;
`endif
    wire imm_op = vop == 3'd1 || vop == 3'd2 || vop == 3'd4 || vop == 3'd6 || (vop == 3'd7 && !x_go);
    assign ad_r = !(imm_op && imm_v) && !(vop == 3'd5 && cq_n == CQD) && !(vop == 3'd7 && x_go && xp_c < 3'd5 && x_act[xp_c]) && !x_hold_new;
    wire acc = ad_v && ad_r;
    wire is_armb = acc && vop == 3'd1, is_armr = acc && vop == 3'd2, is_arm = acc && vop == 3'd3;
    wire is_pid = acc && vop == 3'd4, is_prd = acc && vop == 3'd5;
    wire [1:0] arm_s = arg[20:19];
    wire is_larm = acc && vop == 3'd6, is_xmap = acc && vop == 3'd7 && !x_go, is_xgo = acc && vop == 3'd7 && x_go;
    wire is_bad = acc && (vop == 3'd0 || (vop == 3'd7 && xp_c > 3'd4));
    reg [89:0] id_r;                    // {shared, expert 9, identity 74} in parts of 18
    always @(posedge clk) if (!rn) id_r <= 90'd0; else if (is_pid && arg[20:18] <= 3'd4) id_r[18*arg[20:18] +: 18] <= arg[17:0];
    // P2RD queue {identity 74, base 14, nw 7, expert 9, shared 1, tag 8} = 113
    localparam integer QW = 113, QB = (CQD > 1) ? $clog2(CQD) : 1;
    reg [QW-1:0] cq [0:CQD-1];
    reg [QB-1:0] cq_h, cq_t;
    wire [QW-1:0] cq_in = {id_r[73:0], arg[20:7], arg[6:0], id_r[82:74], id_r[83], ctag};
    reg r_act; reg [13:0] r_base; reg [6:0] r_w, r_nw; reg [73:0] r_id; reg [8:0] r_ex; reg r_sh; reg [7:0] r_tag;
    reg [$clog2(P2D+1):0] cr;
    wire r_iss = r_act && cr != 0;
    wire r_last = r_iss && r_w == r_nw;
    wire cq_pop = (!r_act || r_last) && cq_n != 0;
    wire cq_push = is_prd;
    always @(posedge clk) begin
        if (!rn) begin cq_h <= 0; cq_t <= 0; cq_n <= 0; r_act <= 1'b0; cr <= P2D; end
        else begin
            if (cq_push) begin cq[cq_t] <= cq_in; cq_t <= (cq_t == CQD - 1) ? 0 : cq_t + 1'b1; end
            if (cq_pop) cq_h <= (cq_h == CQD - 1) ? 0 : cq_h + 1'b1;
            cq_n <= cq_n + cq_push - cq_pop;
            if (cq_pop) begin
                r_act <= 1'b1; {r_id, r_base, r_nw, r_ex, r_sh, r_tag} <= cq[cq_h]; r_w <= 7'd0;
            end else if (r_last) r_act <= 1'b0;
            if (r_iss && !r_last) r_w <= r_w + 7'd1;
            cr <= cr - r_iss + a_p2c;
        end
    end

    // ---------------------------------------------------------------- X streamers (VM -> consumer die buses)
    // XMAP {xp, bus lane, nrows - 1}, XGO {xp, base}: streamer xp reads base .. base + nrows - 1, one row a cycle, on its
    // port (X0 p6, X1 p7, X2 p2, X3 p8, X4 p9); every read carries its bus lane id down the tile chain (unused write
    // data field) so the BE routes the row to that lane of the die read buses.  Done at the last read issued.
    reg [3:0] x_bus [0:4]; reg [12:0] x_n [0:4], x_c [0:4]; reg [13:0] x_b [0:4]; reg [7:0] x_tag [0:4];
    reg [4:0] x_dp;                       // done pending
    wire [4:0] x_iss = x_act;
    wire [4:0] x_last;
    genvar gx;
    generate for (gx = 0; gx < 5; gx = gx + 1) begin : g_xl
        assign x_last[gx] = x_act[gx] && x_c[gx] == x_n[gx];
    end endgenerate

    always @(posedge clk) begin : p_l507 integer xi;
        if (!rn) x_act <= 5'd0;
        else for (xi = 0; xi < 5; xi = xi + 1) begin
            if (is_xmap && xp_c == xi[2:0]) begin x_bus[xi] <= arg[16:13]; x_n[xi] <= arg[12:0]; end
`ifdef OT_SPVM_XGOS
            if (is_xgo && xp_c == xi[2:0]) begin x_act[xi] <= !arg[16]; x_b[xi] <= arg[13:0]; x_c[xi] <= 13'd0; x_tag[xi] <= ctag; end
            else if (x_rel[xi]) x_act[xi] <= 1'b1;
`else
            if (is_xgo && xp_c == xi[2:0]) begin x_act[xi] <= 1'b1; x_b[xi] <= arg[13:0]; x_c[xi] <= 13'd0; x_tag[xi] <= ctag; end
`endif
            else if (x_last[xi]) x_act[xi] <= 1'b0;
            else if (x_act[xi]) x_c[xi] <= x_c[xi] + 13'd1;
        end
    end
    wire [13:0] x_row0 = x_b[0] + {1'b0, x_c[0]}, x_row1 = x_b[1] + {1'b0, x_c[1]}, x_row2 = x_b[2] + {1'b0, x_c[2]},
                x_row3 = x_b[3] + {1'b0, x_c[3]}, x_row4 = x_b[4] + {1'b0, x_c[4]};

    // ---- end verbatim
    // LARM: per-lane out-pin flops = the flat ra_v[0] / rb[0] of each lane
    wire [3:0] larm_g = arg[20:17];
    (* keep = 1 *) reg [9:0] arm_vk; (* keep = 1 *) reg [139:0] arm_bk;
    always @* begin arm_v = arm_vk; arm_base = arm_bk; end
    always @(posedge clk) begin : p_la integer l;
        for (l = 0; l < 10; l = l + 1) begin
            arm_bk[14*l +: 14] <= arg[13:0];
            if (!rn) arm_vk[l] <= 1'b0;
            else arm_vk[l] <= is_larm && larm_g == ((l < 2) ? 4'd0 : (l < 6) ? 4'd4 : (l == 6) ? 4'd5 : (l == 7) ? 4'd6 : 4'd7);
        end
    end
    // own order registers (read ports: {v, row} a slice; the data tag only in slice 0, on x_o)
    wire [6*60-1:0] fs; wire [6*32-1:0] ko;
    dsfd_vm_fob #(.WEV(0), .DF(0), .DX(4)) u_b2 (.clk(clk), .rn(rn), .i_v(x_iss[2]), .i_we(1'b0), .i_row(x_row2), .i_m(16'hffff),
        .i_d({508'd0, x_bus[2]}), .s_o(fs[0*60 +: 60]), .x_o(x_o[3:0]), .k_o(ko[0*32 +: 32]));
    dsfd_vm_fob #(.WEV(0), .DF(0), .DX(92)) u_b5 (.clk(clk), .rn(rn), .i_v(r_iss), .i_we(1'b0), .i_row(r_base + {7'd0, r_w}), .i_m(16'hffff),
        .i_d({420'd0, r_id, r_ex, r_sh, r_last, r_w}), .s_o(fs[1*60 +: 60]), .x_o(x_o[95:4]), .k_o(ko[1*32 +: 32]));
    dsfd_vm_fob #(.WEV(0), .DF(0), .DX(4)) u_b6 (.clk(clk), .rn(rn), .i_v(x_iss[0]), .i_we(1'b0), .i_row(x_row0), .i_m(16'hffff),
        .i_d({508'd0, x_bus[0]}), .s_o(fs[2*60 +: 60]), .x_o(x_o[99:96]), .k_o(ko[2*32 +: 32]));
    dsfd_vm_fob #(.WEV(0), .DF(0), .DX(4)) u_b7 (.clk(clk), .rn(rn), .i_v(x_iss[1]), .i_we(1'b0), .i_row(x_row1), .i_m(16'hffff),
        .i_d({508'd0, x_bus[1]}), .s_o(fs[3*60 +: 60]), .x_o(x_o[103:100]), .k_o(ko[3*32 +: 32]));
    dsfd_vm_fob #(.WEV(0), .DF(0), .DX(4)) u_b8 (.clk(clk), .rn(rn), .i_v(x_iss[3]), .i_we(1'b0), .i_row(x_row3), .i_m(16'hffff),
        .i_d({508'd0, x_bus[3]}), .s_o(fs[4*60 +: 60]), .x_o(x_o[107:104]), .k_o(ko[4*32 +: 32]));
    dsfd_vm_fob #(.WEV(0), .DF(0), .DX(4)) u_b9 (.clk(clk), .rn(rn), .i_v(x_iss[4]), .i_we(1'b0), .i_row(x_row4), .i_m(16'hffff),
        .i_d({508'd0, x_bus[4]}), .s_o(fs[5*60 +: 60]), .x_o(x_o[111:108]), .k_o(ko[5*32 +: 32]));
    genvar gj, gs, gp;
    generate for (gj = 0; gj < 6; gj = gj + 1) begin : g_o
        for (gs = 0; gs < 4; gs = gs + 1) begin : g_s
            assign s_o[(6*gs + gj)*15 +: 15] = fs[60*gj + 15*gs +: 15];
        end
    end endgenerate
    // the 28 k copies -> named as the order register for the verbatim counter below, whose kq[0] (KD 1 here) is therefore
    // the in-pin flop = the flat kq[KD-1].  Flat KD = `VMFE_KD: an EXTERNAL copy passes the source leaf's out-pin flop (kq[0]),
    // KP = KD - 2 mid-hop relay tiles in the parent (B8: KD 3, one dsfd_vm_frm stage: the 16 lanes' copies span 1,212 um, no
    // fcn position is within one 500-um wire of both ends) and this in-pin flop; the OWN ports' copies and the ARM ops take
    // KP registers here instead (ko_q / pa_q), so every port and the ARM ops reach the counter on the same cycle.
    localparam integer KP = `VMFE_KD - 2;
    wire [191:0] ko_d;
    generate if (KP > 0) begin : g_kp
        reg [191:0] ko_q [0:KP-1]; integer qi;
        always @(posedge clk) begin
            if (!rn) for (qi = 0; qi < KP; qi = qi + 1) ko_q[qi] <= 192'd0;
            else begin ko_q[0] <= ko; for (qi = 1; qi < KP; qi = qi + 1) ko_q[qi] <= ko_q[qi-1]; end
        end
        assign ko_d = ko_q[KP-1];
    end else begin : g_nkp
        assign ko_d = ko;
    end endgenerate
    wire [NP-1:0] b_v, b_we; wire [NP*RA-1:0] b_row; wire [NP*16-1:0] b_m;
    generate for (gp = 0; gp < NP; gp = gp + 1) begin : g_k
        localparam integer OWN = (gp == 2) ? 0 : (gp >= 5 && gp <= 9) ? gp - 4 : -1;
        localparam integer EXT = (gp < 2) ? gp : (gp < 5) ? gp - 1 : gp - 6;
        wire [31:0] kw;
        if (OWN >= 0) begin : g_i assign kw = ko_d[32*OWN +: 32]; end
        else begin : g_e assign kw = k_i[32*EXT +: 32]; end
        assign b_v[gp] = kw[31]; assign b_we[gp] = kw[30]; assign b_row[RA*gp +: RA] = kw[29:16]; assign b_m[16*gp +: 16] = kw[15:0];
    end endgenerate
    // ARM ops: pre-register p0_* (+ KP stages pa_q) + kq[0] below = the flat kq_arm*[0 .. KD-1]
    reg p0_armb, p0_armr, p0_arm; reg [23:0] p0_arg; reg [7:0] p0_tag; reg [9:0] p0_user;
`ifdef OT_VMFE_MUT_KQSKIP
    // MUTANT: the ARM ops skip their kq stage (reach the counter one cycle ahead of the port ops)
    always @* begin p0_armb = is_armb; p0_armr = is_armr; p0_arm = is_arm; p0_arg = arg; p0_tag = ctag; p0_user = ad_d[82:73]; end
`else
    always @(posedge clk) begin
        if (!rn) begin p0_armb <= 1'b0; p0_armr <= 1'b0; p0_arm <= 1'b0; end
        else begin p0_armb <= is_armb; p0_armr <= is_armr; p0_arm <= is_arm; end
        p0_arg <= arg; p0_tag <= ctag; p0_user <= ad_d[82:73];
    end
`endif
    wire p_armb, p_armr, p_arm; wire [23:0] p_arg; wire [7:0] p_tag; wire [9:0] p_user;
    generate if (KP > 0) begin : g_pa
        reg [2:0] pa_c [0:KP-1]; reg [41:0] pa_q [0:KP-1]; integer qj;
        always @(posedge clk) begin
            if (!rn) for (qj = 0; qj < KP; qj = qj + 1) pa_c[qj] <= 3'd0;
            else begin pa_c[0] <= {p0_armb, p0_armr, p0_arm}; for (qj = 1; qj < KP; qj = qj + 1) pa_c[qj] <= pa_c[qj-1]; end
            pa_q[0] <= {p0_arg, p0_tag, p0_user}; for (qj = 1; qj < KP; qj = qj + 1) pa_q[qj] <= pa_q[qj-1];
        end
        assign {p_armb, p_armr, p_arm} = pa_c[KP-1]; assign {p_arg, p_tag, p_user} = pa_q[KP-1];
    end else begin : g_npa
        assign {p_armb, p_armr, p_arm} = {p0_armb, p0_armr, p0_arm}; assign {p_arg, p_tag, p_user} = {p0_arg, p0_tag, p0_user};
    end endgenerate
    // ---- verbatim from the flat dsfd_vm_fe (six kq stage-0 sources substituted by the generator)
    // ---------------------------------------------------------------- row-completion counter + early-read check
    // stage K (one cycle after B, the same order): per port and slot {in range, write elements | read}
    reg [NSLOT-1:0] sl_arm, sl_dp, sl_rp, sl_ntf;
    reg [13:0] sl_base [0:NSLOT-1]; reg [14:0] sl_n [0:NSLOT-1]; reg [18:0] sl_need [0:NSLOT-1], sl_cnt [0:NSLOT-1];
    reg [9:0] sl_user [0:NSLOT-1]; reg [7:0] sl_tag [0:NSLOT-1];
    reg [13:0] st_base [0:NSLOT-1]; reg [14:0] st_n [0:NSLOT-1]; reg [NSLOT-1:0] st_ntf;   // ARMB / ARMR staging
    reg [NSLOT*NP-1:0] k_w, k_r;        // registered in-range flags
    reg [NP*5-1:0] k_pc;                // registered popcount of each port's mask
    reg [NP-1:0] k_v, k_we;
    reg [NSLOT-1:0] k_ok;
    // KD relay stages (el1011-ds-vm/fe): the counter sees the order register (28 ports from the full 1,520-um width)
    // AND the ARM ops KD cycles later -- a uniform shift, so the old-range / new-range contract is unchanged
    reg [NP-1:0] kq_v [0:KD-1], kq_we [0:KD-1]; reg [NP*RA-1:0] kq_row [0:KD-1]; reg [NP*16-1:0] kq_m [0:KD-1];
    reg [KD-1:0] kq_armb, kq_armr, kq_arm; reg [23:0] kq_arg [0:KD-1]; reg [7:0] kq_tag [0:KD-1]; reg [9:0] kq_user [0:KD-1];
    always @(posedge clk) begin : p_kq integer i;
        if (!rn) begin
            for (i = 0; i < KD; i = i + 1) kq_v[i] <= {NP{1'b0}};
            kq_armb <= {KD{1'b0}}; kq_armr <= {KD{1'b0}}; kq_arm <= {KD{1'b0}};
        end else begin
            kq_v[0] <= b_v; for (i = 1; i < KD; i = i + 1) kq_v[i] <= kq_v[i-1];
            kq_armb <= {kq_armb, p_armb}; kq_armr <= {kq_armr, p_armr}; kq_arm <= {kq_arm, p_arm};
        end
        kq_we[0] <= b_we; kq_row[0] <= b_row; kq_m[0] <= b_m; kq_arg[0] <= p_arg; kq_tag[0] <= p_tag; kq_user[0] <= p_user;
        for (i = 1; i < KD; i = i + 1) begin
            kq_we[i] <= kq_we[i-1]; kq_row[i] <= kq_row[i-1]; kq_m[i] <= kq_m[i-1];
            kq_arg[i] <= kq_arg[i-1]; kq_tag[i] <= kq_tag[i-1]; kq_user[i] <= kq_user[i-1];
        end
    end
    wire [NP-1:0] kb_v = kq_v[KD-1], kb_we = kq_we[KD-1]; wire [NP*RA-1:0] kb_row = kq_row[KD-1]; wire [NP*16-1:0] kb_m = kq_m[KD-1];
    wire k_armb = kq_armb[KD-1], k_armr = kq_armr[KD-1], k_arm = kq_arm[KD-1];
    wire [23:0] k_arg = kq_arg[KD-1]; wire [7:0] k_tag = kq_tag[KD-1]; wire [9:0] k_user = kq_user[KD-1];
    wire [1:0] k_s = k_arg[20:19];
    integer kk, b;
    reg [4:0] pc;
    reg [15:0] wm;
    always @(posedge clk) begin : p_l672 integer kk, q, b;
        for (q = 0; q < NP; q = q + 1) begin
            wm = kb_m[q*16 +: 16];
            pc = 5'd0; for (b = 0; b < 16; b = b + 1) pc = pc + {4'd0, wm[b]};
            k_pc[5*q +: 5] <= pc;
            for (kk = 0; kk < NSLOT; kk = kk + 1) begin
                k_w[kk*NP + q] <= kb_v[q] && kb_we[q] && kb_row[q*RA +: RA] >= sl_base[kk] &&
                                  {1'b0, kb_row[q*RA +: RA]} < {1'b0, sl_base[kk]} + sl_n[kk];
                k_r[kk*NP + q] <= kb_v[q] && !kb_we[q] && kb_row[q*RA +: RA] >= sl_base[kk] &&
                                  {1'b0, kb_row[q*RA +: RA]} < {1'b0, sl_base[kk]} + sl_n[kk];
            end
        end
        if (!rn) k_v <= {NP{1'b0}}; else k_v <= kb_v;
        // the flags of a slot being ARMed this edge were compared with its OLD range: not counted, not checked
        // (contract: no op into a range in the cycle its ARMN lands)
        k_ok <= ~(k_arm ? ({{(NSLOT-1){1'b0}}, 1'b1} << k_s) : {NSLOT{1'b0}});
    end
    // stage K2 (el1011-ds-vm/fe6: the k_pc -> 28-port sum -> compare -> early path was ~1,525 ps in one cycle): per slot
    // 4 group sums of 7 ports (masked by k_ok) and the read-hit OR are registered; the counter adds the 4 group sums.
    // The counter half of every ARM (sl_arm / sl_cnt / sl_need / tag / user / ntf / t_rdy / rearm) moves one cycle later
    // with them (k2_*), so ARM and op counts keep their order; the range half (sl_base / sl_n, read by stage K's compares)
    // still lands at k_arm.  Effect: slot completion / done / rows-ready one serial cycle later, same order of events.
    reg [7:0] k2_g [0:NSLOT*4-1]; reg [NSLOT-1:0] k2_hr;
    reg k2_arm; reg [1:0] k2_s; reg [18:0] k2_need; reg [7:0] k2_tag; reg [9:0] k2_user; reg k2_ntf;
    always @(posedge clk) begin : p_k2 integer kk, g, q; reg [7:0] a; reg h;
        for (kk = 0; kk < NSLOT; kk = kk + 1) begin
            h = 1'b0;
            for (g = 0; g < 4; g = g + 1) begin
                a = 8'd0;
                for (q = 7 * g; q < 7 * g + 7; q = q + 1) if (k_w[kk*NP + q]) a = a + {3'd0, k_pc[5*q +: 5]};
                k2_g[kk*4 + g] <= k_ok[kk] ? a : 8'd0;
            end
            for (q = 0; q < NP; q = q + 1) if (k_r[kk*NP + q]) h = 1'b1;
            k2_hr[kk] <= h && k_ok[kk];
        end
        if (!rn) k2_arm <= 1'b0; else k2_arm <= k_arm;
        k2_s <= k_s; k2_need <= k_arg[18:0]; k2_tag <= k_tag; k2_user <= k_user; k2_ntf <= st_ntf[k_s];
    end
`ifdef OT_VMFE_FCN_SUM_PIPE
    // Stage K3: reduce the four K2 groups before the wide count/compare.
    // ARM metadata and read hits advance with the same accepted operation.
    reg [9:0] k3_inc [0:NSLOT-1]; reg [NSLOT-1:0] k3_hr;
    reg k3_arm; reg [1:0] k3_s; reg [18:0] k3_need; reg [7:0] k3_tag;
    reg [9:0] k3_user; reg k3_ntf;
    always @(posedge clk) begin : p_k3 integer kk;
        for (kk = 0; kk < NSLOT; kk = kk + 1)
            k3_inc[kk] <= ({2'd0, k2_g[kk*4]} + {2'd0, k2_g[kk*4+1]})
                         + ({2'd0, k2_g[kk*4+2]} + {2'd0, k2_g[kk*4+3]});
        k3_hr <= k2_hr;
        if (!rn) k3_arm <= 1'b0; else k3_arm <= k2_arm;
        k3_s <= k2_s; k3_need <= k2_need; k3_tag <= k2_tag;
        k3_user <= k2_user; k3_ntf <= k2_ntf;
    end
`endif
    reg [9:0] inc [0:NSLOT-1];
    reg [NSLOT-1:0] hit_r, cmpl;
    always @* begin : p_l691 integer kk;
        for (kk = 0; kk < NSLOT; kk = kk + 1) begin
`ifdef OT_VMFE_FCN_SUM_PIPE
`ifdef OT_VMFE_FCN_SUM_PIPE_MUT
            inc[kk] = k3_inc[kk] ^ 10'd1;
`else
            inc[kk] = k3_inc[kk];
`endif
            hit_r[kk] = k3_hr[kk];
`else
            inc[kk] = ({2'd0, k2_g[kk*4]} + {2'd0, k2_g[kk*4 + 1]}) + ({2'd0, k2_g[kk*4 + 2]} + {2'd0, k2_g[kk*4 + 3]});
            hit_r[kk] = k2_hr[kk];
`endif
`ifdef OT_SPVM_MUT_EARLY
            cmpl[kk] = sl_arm[kk] && sl_cnt[kk] + inc[kk] + 19'd1 >= sl_need[kk];   // MUTANT: one element early
`else
            cmpl[kk] = sl_arm[kk] && sl_cnt[kk] + inc[kk] >= sl_need[kk];
`endif
        end
    end
    // P2 done pending: tags of finished P2RD commands, in order (<= CQD + 1 outstanding)
    reg [7:0] pd_q [0:CQD]; reg [$clog2(CQD+2)-1:0] pd_h, pd_t, pd_n;
    reg early, ovf_cr, rearm, ovf_pd;
    reg [NSLOT-1:0] dsel, rsel;
    always @* begin : p_l709 integer kk;
        dsel = {NSLOT{1'b0}}; rsel = {NSLOT{1'b0}};
        for (kk = NSLOT - 1; kk >= 0; kk = kk - 1) begin
            if (sl_dp[kk]) dsel = {{(NSLOT-1){1'b0}}, 1'b1} << kk;
            if (sl_rp[kk]) rsel = {{(NSLOT-1){1'b0}}, 1'b1} << kk;
        end
    end
    wire d_slot = |sl_dp;                      // slot dones first, then P2 dones, then the immediate done
    wire d_p2 = !d_slot && pd_n != 0;
    wire d_x = !d_slot && !d_p2 && x_dp != 5'd0;
    reg [2:0] xsel; integer xq;
    always @* begin xsel = 3'd0; for (xq = 4; xq >= 0; xq = xq - 1) if (x_dp[xq]) xsel = xq[2:0]; end
    wire d_imm = !d_slot && !d_p2 && !d_x && imm_v;
    wire c_w_go = !c_wv[0] || c_wr[0];
    reg [7:0] dsel_tag; reg [9:0] rsel_user;
    always @* begin : p_l724 integer kk;
        dsel_tag = 8'd0; rsel_user = 10'd0;
        for (kk = 0; kk < NSLOT; kk = kk + 1) begin
            if (dsel[kk]) dsel_tag = dsel_tag | sl_tag[kk];
            if (rsel[kk]) rsel_user = rsel_user | sl_user[kk];
        end
    end
    always @(posedge clk) begin : p_l731 integer kk;
        if (!rn) begin
            sl_arm <= 0; sl_dp <= 0; sl_rp <= 0; sl_ntf <= 0; ed_v <= 1'b0; c_wv <= 1'b0; t_rdy <= 0; imm_v <= 1'b0; x_dp <= 5'd0;
            pd_h <= 0; pd_t <= 0; pd_n <= 0;
            early <= 1'b0; ovf_cr <= 1'b0; rearm <= 1'b0; ovf_pd <= 1'b0;
            for (kk = 0; kk < NSLOT; kk = kk + 1) begin sl_base[kk] <= 14'd0; sl_n[kk] <= 15'd0; end
        end else begin
            for (kk = 0; kk < NSLOT; kk = kk + 1) begin
                if (sl_arm[kk]) sl_cnt[kk] <= sl_cnt[kk] + {9'd0, inc[kk]};
                if (hit_r[kk] && sl_arm[kk] && !cmpl[kk]) early <= 1'b1;
                if (cmpl[kk]) begin sl_arm[kk] <= 1'b0; t_rdy[kk] <= 1'b1; end
            end
            if (k_armb) begin st_base[k_s] <= k_arg[13:0]; st_ntf[k_s] <= k_arg[18]; end
            if (k_armr) st_n[k_s] <= k_arg[14:0];
            if (k_arm) begin sl_base[k_s] <= st_base[k_s]; sl_n[k_s] <= st_n[k_s]; end   // range half: stage K compares
`ifdef OT_VMFE_FCN_SUM_PIPE
            if (k3_arm) begin                                                            // counter half: with the K2 sums
                if (sl_arm[k3_s] || sl_dp[k3_s] || sl_rp[k3_s]) rearm <= 1'b1;
                sl_arm[k3_s] <= 1'b1; t_rdy[k3_s] <= 1'b0; sl_ntf[k3_s] <= k3_ntf; sl_user[k3_s] <= k3_user;
                sl_need[k3_s] <= k3_need; sl_cnt[k3_s] <= 19'd0; sl_tag[k3_s] <= k3_tag;
            end
`else
            if (k2_arm) begin                                                            // counter half: with the K2 sums
                if (sl_arm[k2_s] || sl_dp[k2_s] || sl_rp[k2_s]) rearm <= 1'b1;
                sl_arm[k2_s] <= 1'b1; t_rdy[k2_s] <= 1'b0; sl_ntf[k2_s] <= k2_ntf; sl_user[k2_s] <= k2_user;
                sl_need[k2_s] <= k2_need; sl_cnt[k2_s] <= 19'd0; sl_tag[k2_s] <= k2_tag;
            end
`endif
            // engine done output (one a cycle)
            ed_v <= d_slot || d_p2 || d_x || d_imm;
            ed_t <= d_slot ? dsel_tag : d_p2 ? pd_q[pd_h] : d_x ? x_tag[xsel] : imm_t;
            x_dp <= (x_dp & ~(d_x ? (5'd1 << xsel) : 5'd0)) | x_last;
            sl_dp <= (sl_dp & ~(d_slot ? dsel : {NSLOT{1'b0}})) | cmpl;
            if (d_imm) imm_v <= 1'b0;
            if (acc && imm_op) begin imm_v <= 1'b1; imm_t <= ctag; end
            // P2 done queue
            if (r_last) begin pd_q[pd_t] <= r_tag; pd_t <= (pd_t == CQD) ? 0 : pd_t + 1'b1; end
            if (d_p2) pd_h <= (pd_h == CQD) ? 0 : pd_h + 1'b1;
            pd_n <= pd_n + r_last - d_p2;
            if (r_last && pd_n == CQD + 1) ovf_pd <= 1'b1;
            // rows-ready output (held until the ep takes it)
            if (c_w_go) begin
                c_wv <= |sl_rp; c_wd <= rsel_user;
                sl_rp <= (sl_rp & ~rsel) | (cmpl & sl_ntf);
            end else sl_rp <= sl_rp | (cmpl & sl_ntf);
            if (cr > P2D) ovf_cr <= 1'b1;
        end
    end
`ifndef SYNTHESIS
    always @(posedge clk) if (rn) for (kk = 0; kk < NSLOT; kk = kk + 1)
        if (hit_r[kk] && sl_arm[kk] && !cmpl[kk])
            $error("SPVM EARLY_READ: read into slot %0d range [%0d, +%0d) at %0d of %0d elements (ports %b)", kk, sl_base[kk],
                   sl_n[kk], sl_cnt[kk], sl_need[kk], k_r[kk*NP +: NP]);
`endif

`ifdef OT_SPVM_XGOS
    // XGOS release: x_fr[s] = slot s completed and not re-armed since (set by its completion, cleared when an ARMN of s is
    // accepted, in command order with the XGOS).  A waiting streamer is released by its slot's completion pulse; an XGOS
    // that arrives after the completion is released at once.  One registered cycle (x_rel) before the streamer starts.
    reg [NSLOT-1:0] x_fr; reg [1:0] x_ws [0:4];
    always @(posedge clk) begin : p_xgos integer xi, kk;
        if (!rn) begin x_wt <= 5'd0; x_rel <= 5'd0; x_fr <= {NSLOT{1'b0}}; end
        else begin
            for (kk = 0; kk < NSLOT; kk = kk + 1) begin
                if (cmpl[kk]) x_fr[kk] <= 1'b1;
                if (is_arm && arm_s == kk[1:0]) x_fr[kk] <= 1'b0;
            end
            for (xi = 0; xi < 5; xi = xi + 1) begin
                x_rel[xi] <= 1'b0;
                if (is_xgo && arg[16] && xp_c == xi[2:0]) begin
`ifdef OT_SPVM_MUT_XGOS_EARLY
                    x_rel[xi] <= 1'b1;                                              // MUTANT: starts without its slot
`else
                    if (x_fr[arg[15:14]] || cmpl[arg[15:14]]) x_rel[xi] <= 1'b1;
                    else begin x_wt[xi] <= 1'b1; x_ws[xi] <= arg[15:14]; end
`endif
                end else if (x_wt[xi] && cmpl[x_ws[xi]]) begin x_wt[xi] <= 1'b0; x_rel[xi] <= 1'b1; end
            end
        end
    end
`endif
    // ---- end verbatim
    // FE status: fault wires from the other leaves enter pin flops (sticky sources; rule 3)
    reg [15:0] clf_q; reg so_q, ovr_q, sflt_q, err_q;
    always @(posedge clk) begin clf_q <= clf_i; so_q <= so_i; ovr_q <= ovr_i; sflt_q <= sflt_i; err_q <= err_i; end
    wire [3:0] clf = clf_q[3:0] | clf_q[7:4] | clf_q[11:8] | clf_q[15:12];
    (* keep = 1 *) reg [3:0] rf_k;
    always @* rf_o = rf_k;
    always @(posedge clk) begin
        if (!rn) fe_flt <= 16'd0;
        else fe_flt <= fe_flt | {so_q, ovr_q, ad_flt, cap_src_flt, clf, is_bad, ovf_pd, rearm, sflt_q, ovf_cr, 1'b0, err_q, early};
        rf_k <= {4{|fe_flt}};
    end
`ifdef OT_SPVM_RESET_ACK
    dsfd_vm_reset_ack #(.N(1)) u_reset_ack (.clk(clk), .request_n(rst[0]), .local_release(rn), .consumer_live(1'b1), .ack(rst_ack[0]));
    dsfd_vm_reset_ack #(.N(1)) u_stream_ack (.clk(cks[0]), .request_n(rss[0]), .local_release(rns), .consumer_live(1'b1), .ack(rst_ack_s[0]));
`endif
endmodule

// ================================================================ parent: wires + leaf instances only
// Bundles: b 0..3 = capture ports 12 + 4b .. 15 + 4b (from fxs b); b 4 = ports 0, 1, 3, 4 (fcw, fcc); b 5 = ports 2,
// 5 .. 9 (fcn), 10, 11 (fld), rf and the slice-0 tags.  Every (port, slice) crosses `VMFE_R relay tiles
// carrying its non-constant bits (table at the relay masters); the constants are TIED at the dsfd_vm_fsr pins here.
// Reset tree (parent wiring only, re-routable without touching a leaf): fcn.rn_o -> fld, fcc, fcw, fxs 0..3;
// fld -> flt 0 -> .. -> flt 9; bundle source -> relay(b, slice 0, 0) -> stage chain / slice chain; relay -> fsr.
module dsfd_vm_fe_h #(parameter integer BANK_XOR=0) (
    input  wire [0:0]    ck,
    input  wire [0:0]    rst,
    input  wire [0:0]    cks,
    input  wire [0:0]    rss,
    input  wire [0:0]    f_swv, input wire [526:0] f_swd, output wire [0:0] t_swg,
    input  wire [0:0]    f_srv, input wire [30:0]  f_srd, output wire [0:0] t_srg,
    output wire [52:0]   t_ks,
    input  wire [13375:0] f_cap,
    input  wire [0:0]    vwe, input wire [13:0] vwa, input wire [511:0] vwd,
    input  wire [0:0]    vre, input wire [13:0] vra,
    input  wire [0:0]    cv, input wire [83:0] cd, output wire [0:0] dv, output wire [7:0] dt,
    input  wire [1026:0] f_svc,
    input  wire [2099:0] f_coll,
    output wire [2:0]    t_cts,
    input  wire [514:0]  f_sel, input wire [514:0] f_col,
    input  wire [1025:0] f_hc,
    output wire [0:0]    c_wv, output wire [9:0] c_wd, input wire [0:0] c_wr,
    output wire [3:0]    t_rdy,
    input  wire [0:0]    f_p2c,
    output wire [111:0]   m_v,
    output wire [111:0]   m_we,
    output wire [1567:0]  m_row,
    output wire [447:0]   m_mask,
    output wire [14335:0] m_d,
    output wire [15:0]    m_rf,
    output wire [15:0]    fe_flt
`ifdef OT_SPVM_RESET_ACK
    , output wire [40+24*`VMFE_R:0] rst_ack, output wire [3:0] rst_ack_s
`endif
);
    localparam integer R = `VMFE_R;
    wire [4*2352-1:0] cap_so;           // fxs gi: lane j, slice s at [2352*gi + (4*j + s)*147 +: 147]
    wire [4*5-1:0] cap_rno;
    wire [28*32-1:0] kall;
    wire [7:0] rn_cn; wire [0:0] rn_ld; wire [1:0] rn_cc, rn_cw;
    wire [9:0] ll_av, ll_ok, ll_ovf, ll_sf, ll_g, ll_rn, la_v; wire [5259:0] ll_ret; wire [139:0] la_b;
    wire [9:0] ll_gx, la_vx; wire [5259:0] ll_retx; wire [139:0] la_bx;   // after the mid-hop relay tiles
    wire [9:0] ll_avx, ll_okx, ll_ovfx, ll_sfx;
    wire [15:0] clf; wire so_w, ovr_w, sflt_w, err_w; wire [3:0] rf_w;
    wire [359:0] s_cn; wire [111:0] x_cn; wire [1143:0] s_ld; wire [1151:0] s_cc; wire [635:0] s_cw;
    wire [63:0] k_ld, k_cc, k_cw;
    // ---------------- capture: 16 clt + 4 fxs
    genvar gi, gj, gs, gb, gr, gp;
    generate for (gi = 0; gi < 4; gi = gi + 1) begin : g_x
        wire [3:0] w_v, sok; wire [55:0] w_row; wire [63:0] w_m; wire [2047:0] w_d; wire [15:0] w_f; wire [4:0] rno;
        wire [127:0] ko;
        for (gj = 0; gj < 4; gj = gj + 1) begin : g_l
            localparam integer G = 4*gi + gj;
            dsfd_vm_clt u_l (.ck(ck), .rn(rno[gj]), .sok(sok[gj]), .gid(G[3:0]), .f_c(f_cap[832*G +: 832]),
                .w_v(w_v[gj]), .w_row(w_row[14*gj +: 14]), .w_m(w_m[16*gj +: 16]), .w_d(w_d[512*gj +: 512]),
                .flt(w_f[4*gj +: 4])
`ifdef OT_SPVM_RESET_ACK
                , .reset_epoch_n(rst[0]), .rst_ack(rst_ack[G])
`endif
                );
            assign kall[32*(12 + G) +: 32] = ko[32*gj +: 32];
        end
        dsfd_vm_fxs u_x (.ck(ck), .rni(rn_cn[3 + gi]), .w_v(w_v), .w_row(w_row), .w_m(w_m), .w_d(w_d), .w_flt(w_f),
            .s_o(cap_so[2352*gi +: 2352]), .k_o(ko), .clf_o(clf[4*gi +: 4]), .sok_o(sok), .rn_o(rno)
`ifdef OT_SPVM_RESET_ACK
                , .reset_epoch_n(rst[0]), .rst_ack(rst_ack[20+gi])
`endif
                );
        assign cap_rno[5*gi +: 5] = rno;
    end endgenerate
    // ---------------- landing: 10 flt + fld
    generate for (gi = 0; gi < 10; gi = gi + 1) begin : g_ll
        localparam [2:0] ST = (gi < 2) ? 3'd2 : (gi < 6) ? 3'd4 : (gi < 8) ? 3'd1 : 3'd2;
        localparam [1:0] OF = (gi < 2) ? gi : (gi < 6) ? gi - 2 : (gi < 8) ? 0 : gi - 8;
        wire pv, pm, pf; wire [1:0] pt; wire [511:0] pd;
        if (gi < 2) begin : g_sv
            assign pv = f_svc[0]; assign pt = 2'd0; assign pm = 1'b1; assign pd = f_svc[1 + 512*gi +: 512]; assign pf = f_svc[1026];
        end else if (gi < 6) begin : g_co
            assign pv = f_coll[0]; assign pt = f_coll[2:1]; assign pm = f_coll[6 + gi - 2];
            assign pd = f_coll[52 + 512*(gi - 2) +: 512]; assign pf = f_coll[41];
        end else if (gi == 6) begin : g_se
            assign pv = f_sel[0]; assign pt = 2'd0; assign pm = 1'b1; assign pd = f_sel[512:1]; assign pf = f_sel[514];
        end else if (gi == 7) begin : g_cl
            assign pv = f_col[0]; assign pt = 2'd0; assign pm = 1'b1; assign pd = f_col[512:1]; assign pf = f_col[514];
        end else begin : g_hc
            assign pv = f_hc[512 + 513*(gi - 8)]; assign pt = 2'd0; assign pm = 1'b1; assign pd = f_hc[513*(gi - 8) +: 512];
            assign pf = 1'b0;
        end
        wire rni_l;
        if (gi == 0) begin : g_r0 assign rni_l = rn_ld[0]; end else begin : g_rn assign rni_l = ll_rn[gi - 1]; end
        dsfd_vm_flt u_t (.ck(ck), .rni(rni_l), .p_v(pv), .p_t(pt), .p_m(pm), .p_d(pd), .p_flt(pf), .stride(ST), .off(OF),
            .g(ll_gx[gi]), .arm_v(la_vx[gi]), .arm_base(la_bx[14*gi +: 14]),
            .av(ll_av[gi]), .ret(ll_ret[526*gi +: 526]), .ok(ll_ok[gi]), .ovf(ll_ovf[gi]), .sflt(ll_sf[gi]), .rn_o(ll_rn[gi])
`ifdef OT_SPVM_RESET_ACK
                , .reset_epoch_n(rst[0]), .rst_ack(rst_ack[24+gi])
`endif
                );
        // the lane's mid-hop relay tile (one stage on g / arm / ret / flags: the contract's LGL 3, LAL 3, LDL 3, LVX 1)
        if (`VMFE_LGL != 3 || `VMFE_LAL != 3 || `VMFE_LDL != 3 || `VMFE_LVX != 1) begin : g_cfg
            dsfd_vm_frm_stage_mismatch u_err ();
        end
        wire [3:0] fo;
        dsfd_vm_frm u_m (.ck(ck), .r_i(ll_ret[526*gi +: 526]), .r_o(ll_retx[526*gi +: 526]),
            .f_i({ll_sf[gi], ll_ovf[gi], ll_ok[gi], ll_av[gi]}), .f_o(fo), .g_i(ll_g[gi]), .g_o(ll_gx[gi]),
            .a_i({la_v[gi], la_b[14*gi +: 14]}), .a_o({la_vx[gi], la_bx[14*gi +: 14]}));
`ifdef OT_VMFE_MUT_AVBYP
        if (gi == 3) begin : g_mut            // MUTANT: lane 3's flags skip their relay stage
            assign {ll_sfx[gi], ll_ovfx[gi], ll_okx[gi], ll_avx[gi]} = {ll_sf[gi], ll_ovf[gi], ll_ok[gi], ll_av[gi]};
        end else
`endif
        begin : g_f assign {ll_sfx[gi], ll_ovfx[gi], ll_okx[gi], ll_avx[gi]} = fo; end
    end endgenerate
    dsfd_vm_fld u_ld (.ck(ck), .rni(rn_cn[0]), .av(ll_avx), .ret(ll_retx), .ok(ll_okx[5:2]), .ovf(ll_ovfx), .sflt(ll_sfx),
        .g(ll_g), .s_o(s_ld), .k_o(k_ld), .t_cts(t_cts), .ovr_o(ovr_w), .sflt_o(sflt_w), .rn_o(rn_ld)
`ifdef OT_SPVM_RESET_ACK
                , .reset_epoch_n(rst[0]), .rst_ack(rst_ack[34])
`endif
                );
    // ---------------- central
    dsfd_vm_fcc u_cc (.ck(ck), .rni(rn_cn[1]), .cks(cks), .rss(rss), .rst(rst), .vwe(vwe), .vwa(vwa), .vwd(vwd), .vre(vre), .vra(vra),
        .s_o(s_cc), .k_o(k_cc), .so_o(so_w), .rn_o(rn_cc)
`ifdef OT_SPVM_RESET_ACK
                , .rst_ack(rst_ack[39+:2]), .rst_ack_s(rst_ack_s[2+:2])
`endif
                );
    dsfd_vm_fcw u_cw (.ck(ck), .rni(rn_cn[2]), .rst(rst), .f_swv(f_swv), .f_swd(f_swd), .t_swg(t_swg), .f_srv(f_srv),
        .f_srd(f_srd), .t_srg(t_srg), .t_ks(t_ks), .s_o(s_cw), .k_o(k_cw), .err_o(err_w), .rn_o(rn_cw)
`ifdef OT_SPVM_RESET_ACK
                , .rst_ack(rst_ack[35+:2])
`endif
                );
    // counter copies: source leaf out pin -> [mid-hop relay tile, KD 3] -> fcn in pin.  The relay master is dsfd_vm_frm (546
    // reset-free flops, CLOSED view): u_kl = k_cw, k_cc, k_ld + lanes 0 .. 7 (448 b), u_kr = lanes 8 .. 15 (256 b); only its
    // r lane is used (unused inputs tied, as the constants at the fsr pins).
    wire [703:0] k_src = {kall[28*32-1:12*32], k_ld, k_cc, k_cw};
    wire [703:0] k_ext;
    generate if (`VMFE_KD == 3) begin : g_kr
        wire [525:0] kl_o, kr_o;
        dsfd_vm_frm u_kl (.ck(ck), .r_i({78'd0, k_src[447:0]}), .r_o(kl_o), .f_i(4'd0), .f_o(), .g_i(1'b0), .g_o(), .a_i(15'd0), .a_o());
        dsfd_vm_frm u_kr (.ck(ck), .r_i({270'd0, k_src[703:448]}), .r_o(kr_o), .f_i(4'd0), .f_o(), .g_i(1'b0), .g_o(), .a_i(15'd0), .a_o());
        assign k_ext = {kr_o[255:0], kl_o[447:0]};
    end else if (`VMFE_KD == 2) begin : g_nkr
        assign k_ext = k_src;
    end else begin : g_kcfg
        dsfd_vm_fe_h_kd_mismatch u_err ();
    end endgenerate
    dsfd_vm_fcn u_cn (.ck(ck), .rst(rst), .cks(cks), .rss(rss), .cv(cv), .cd(cd), .dv(dv), .dt(dt),
        .f_cq(f_cap[13375:13312]), .f_p2c(f_p2c), .c_wv(c_wv), .c_wd(c_wd), .c_wr(c_wr), .t_rdy(t_rdy),
        .k_i(k_ext), .clf_i(clf), .so_i(so_w), .ovr_i(ovr_w), .sflt_i(sflt_w), .err_i(err_w),
        .s_o(s_cn), .x_o(x_cn), .arm_v(la_v), .arm_base(la_b), .rf_o(rf_w), .fe_flt(fe_flt), .rn_o(rn_cn)
`ifdef OT_SPVM_RESET_ACK
                , .rst_ack(rst_ack[37+:2]), .rst_ack_s(rst_ack_s[0+:2])
`endif
                );
    // ---------------- bundle relay tiles + the 4 slice tiles
    wire [5:0] src_rn = {rn_cn[7], rn_cw[0], cap_rno[19], cap_rno[14], cap_rno[9], cap_rno[4]};
    wire [6*4*R-1:0] xr0, xr1;          // rn_o of relay (b, s, r) at [(4*b + s)*R + r]
    wire [111:0] fi_v, fi_we; wire [1567:0] fi_row; wire [447:0] fi_m; wire [14335:0] fi_d;   // slice-major, as m_*
    wire [3:0] fi_rf;
    generate for (gs = 0; gs < 4; gs = gs + 1) begin : g_bs
        for (gb = 0; gb < 4; gb = gb + 1) begin : g_c          // capture bundles: 4 lanes of fxs gb -> dsfd_vm_fxr x R
            wire [3:0] xv [0:R]; wire [583:0] xp [0:R];
            for (gj = 0; gj < 4; gj = gj + 1) begin : g_j
`ifdef OT_SPVM_SLOC
                // FE (a): bundle (gb, gs) = segment gs of fxs gb's 4 lanes -> slice gb, ports 12 + 4 gj + gs (no crossbar)
                localparam integer P = 12 + 4*gj + gs, D = gb;
`else
                localparam integer P = 12 + 4*gb + gj, D = gs;
`endif
                assign xv[0][gj] = cap_so[2352*gb + (4*gj + gs)*147 + 146];
                assign xp[0][146*gj +: 146] = cap_so[2352*gb + (4*gj + gs)*147 +: 146];
                assign fi_v[28*D + P] = xv[R][gj]; assign fi_we[28*D + P] = 1'b1;
                assign fi_row[14*(28*D + P) +: 14] = xp[R][146*gj + 132 +: 14];
                assign fi_m[4*(28*D + P) +: 4] = xp[R][146*gj + 128 +: 4];
                assign fi_d[128*(28*D + P) +: 128] = xp[R][146*gj +: 128];
            end
            for (gr = 0; gr < R; gr = gr + 1) begin : g_r
                wire rni_x;
                if (gs == 0 && gr == 0) begin : g_ra assign rni_x = src_rn[gb]; end
                else if (gs == 0) begin : g_rc assign rni_x = xr0[(4*gb)*R + gr - 1]; end
                else begin : g_rd assign rni_x = xr1[(4*gb + gs - 1)*R + gr]; end
`ifdef OT_VMFE_MUT_FXR1
                if (gb == 1 && gs == 2 && gr == 0) begin : g_mut   // MUTANT: one relay stage fewer for port 16 of slice 2
                    wire [3:0] yv; wire [583:0] yp;
                    dsfd_vm_fxr u_r (.ck(ck), .rni(rni_x), .i_v(xv[gr]), .i(xp[gr]), .o_v(yv), .o(yp),
                        .rn_o({xr1[(4*gb + gs)*R + gr], xr0[(4*gb + gs)*R + gr]})
`ifdef OT_SPVM_RESET_ACK
                , .reset_epoch_n(rst[0]), .rst_ack(rst_ack[41+(4*gb+gs)*R+gr])
`endif
                );
                    reg [146:0] sk; always @(posedge ck[0]) sk <= {xv[gr][0], xp[gr][145:0]};
                    assign xv[gr+1] = {yv[3:1], sk[146]}; assign xp[gr+1] = {yp[583:146], sk[145:0]};
                end else
`endif
                begin : g_t
                    dsfd_vm_fxr u_r (.ck(ck), .rni(rni_x), .i_v(xv[gr]), .i(xp[gr]), .o_v(xv[gr+1]), .o(xp[gr+1]),
                        .rn_o({xr1[(4*gb + gs)*R + gr], xr0[(4*gb + gs)*R + gr]})
`ifdef OT_SPVM_RESET_ACK
                , .reset_epoch_n(rst[0]), .rst_ack(rst_ack[41+(4*gb+gs)*R+gr])
`endif
                );
                end
            end
        end
        if (1) begin : g_b4                 // bundle 4: ports 0, 1, 3, 4 -> dsfd_vm_fxa x R
            wire [3:0] xv [0:R]; wire [442:0] xp [0:R];
            if (1) begin : g_p0
                wire [143:0] sw = s_cw[159*gs +: 144];
                assign xv[0][0] = sw[143]; assign xp[0][0 +: 143] = sw[142:0];
                wire [142:0] ew = xp[R][0 +: 143];
                assign fi_v[28*gs + 0] = xv[R][0]; assign fi_we[28*gs + 0] = ew[142];
                assign fi_row[14*(28*gs + 0) +: 14] = ew[128 +: 14]; assign fi_m[4*(28*gs + 0) +: 4] = 4'hf;
                assign fi_d[128*(28*gs + 0) +: 128] = ew[127:0];
            end
            if (1) begin : g_p1
                wire [14:0] sw = s_cw[159*gs + 144 +: 15];
                assign xv[0][1] = sw[14]; assign xp[0][143 +: 14] = sw[13:0];
                wire [13:0] ew = xp[R][143 +: 14];
                assign fi_v[28*gs + 1] = xv[R][1]; assign fi_we[28*gs + 1] = 1'b0;
                assign fi_row[14*(28*gs + 1) +: 14] = ew[0 +: 14]; assign fi_m[4*(28*gs + 1) +: 4] = 4'hf;
                assign fi_d[128*(28*gs + 1) +: 128] = 128'd0;
            end
            if (1) begin : g_p3
                wire [143:0] sw = s_cc[(2*gs + 0)*144 +: 144];
                assign xv[0][2] = sw[143]; assign xp[0][157 +: 143] = sw[142:0];
                wire [142:0] ew = xp[R][157 +: 143];
                assign fi_v[28*gs + 3] = xv[R][2]; assign fi_we[28*gs + 3] = ew[142];
                assign fi_row[14*(28*gs + 3) +: 14] = ew[128 +: 14]; assign fi_m[4*(28*gs + 3) +: 4] = 4'hf;
                assign fi_d[128*(28*gs + 3) +: 128] = ew[127:0];
            end
            if (1) begin : g_p4
                wire [143:0] sw = s_cc[(2*gs + 1)*144 +: 144];
                assign xv[0][3] = sw[143]; assign xp[0][300 +: 143] = sw[142:0];
                wire [142:0] ew = xp[R][300 +: 143];
                assign fi_v[28*gs + 4] = xv[R][3]; assign fi_we[28*gs + 4] = ew[142];
                assign fi_row[14*(28*gs + 4) +: 14] = ew[128 +: 14]; assign fi_m[4*(28*gs + 4) +: 4] = 4'hf;
                assign fi_d[128*(28*gs + 4) +: 128] = ew[127:0];
            end
            for (gr = 0; gr < R; gr = gr + 1) begin : g_r
                wire rni_x;
                if (gs == 0 && gr == 0) begin : g_a assign rni_x = src_rn[4]; end
                else if (gs == 0) begin : g_c assign rni_x = xr0[(4*4)*R + gr - 1]; end
                else begin : g_d assign rni_x = xr1[(4*4 + gs - 1)*R + gr]; end
                dsfd_vm_fxa u_r (.ck(ck), .rni(rni_x), .i_v(xv[gr]), .i(xp[gr]), .o_v(xv[gr+1]), .o(xp[gr+1]),
                    .rn_o({xr1[(4*4 + gs)*R + gr], xr0[(4*4 + gs)*R + gr]})
`ifdef OT_SPVM_RESET_ACK
                , .reset_epoch_n(rst[0]), .rst_ack(rst_ack[41+(4*4+gs)*R+gr])
`endif
                );
            end
        end
        if (1) begin : g_b5                 // bundle 5: ports 2, 5, 6, 7, 8, 9, 10, 11 -> dsfd_vm_fxb x R
            wire [7:0] xv [0:R]; wire [480:0] xp [0:R];
            if (1) begin : g_p2
                wire [14:0] sw = s_cn[(6*gs + 0)*15 +: 15];
                assign xv[0][0] = sw[14]; assign xp[0][0 +: 14] = sw[13:0];
                wire [13:0] ew = xp[R][0 +: 14];
                assign fi_v[28*gs + 2] = xv[R][0]; assign fi_we[28*gs + 2] = 1'b0;
                assign fi_row[14*(28*gs + 2) +: 14] = ew[0 +: 14]; assign fi_m[4*(28*gs + 2) +: 4] = 4'hf;
                if (gs == 0) begin : g_tag assign fi_d[128*(28*gs + 2) +: 128] = {124'd0, xp[R][369 +: 4]}; end
                else begin : g_ntag assign fi_d[128*(28*gs + 2) +: 128] = 128'd0; end
            end
            if (1) begin : g_p5
                wire [14:0] sw = s_cn[(6*gs + 1)*15 +: 15];
                assign xv[0][1] = sw[14]; assign xp[0][14 +: 14] = sw[13:0];
                wire [13:0] ew = xp[R][14 +: 14];
                assign fi_v[28*gs + 5] = xv[R][1]; assign fi_we[28*gs + 5] = 1'b0;
                assign fi_row[14*(28*gs + 5) +: 14] = ew[0 +: 14]; assign fi_m[4*(28*gs + 5) +: 4] = 4'hf;
                if (gs == 0) begin : g_tag assign fi_d[128*(28*gs + 5) +: 128] = {36'd0, xp[R][373 +: 92]}; end
                else begin : g_ntag assign fi_d[128*(28*gs + 5) +: 128] = 128'd0; end
            end
            if (1) begin : g_p6
                wire [14:0] sw = s_cn[(6*gs + 2)*15 +: 15];
                assign xv[0][2] = sw[14]; assign xp[0][28 +: 14] = sw[13:0];
                wire [13:0] ew = xp[R][28 +: 14];
                assign fi_v[28*gs + 6] = xv[R][2]; assign fi_we[28*gs + 6] = 1'b0;
                assign fi_row[14*(28*gs + 6) +: 14] = ew[0 +: 14]; assign fi_m[4*(28*gs + 6) +: 4] = 4'hf;
                if (gs == 0) begin : g_tag assign fi_d[128*(28*gs + 6) +: 128] = {124'd0, xp[R][465 +: 4]}; end
                else begin : g_ntag assign fi_d[128*(28*gs + 6) +: 128] = 128'd0; end
            end
            if (1) begin : g_p7
                wire [14:0] sw = s_cn[(6*gs + 3)*15 +: 15];
                assign xv[0][3] = sw[14]; assign xp[0][42 +: 14] = sw[13:0];
                wire [13:0] ew = xp[R][42 +: 14];
                assign fi_v[28*gs + 7] = xv[R][3]; assign fi_we[28*gs + 7] = 1'b0;
                assign fi_row[14*(28*gs + 7) +: 14] = ew[0 +: 14]; assign fi_m[4*(28*gs + 7) +: 4] = 4'hf;
                if (gs == 0) begin : g_tag assign fi_d[128*(28*gs + 7) +: 128] = {124'd0, xp[R][469 +: 4]}; end
                else begin : g_ntag assign fi_d[128*(28*gs + 7) +: 128] = 128'd0; end
            end
            if (1) begin : g_p8
                wire [14:0] sw = s_cn[(6*gs + 4)*15 +: 15];
                assign xv[0][4] = sw[14]; assign xp[0][56 +: 14] = sw[13:0];
                wire [13:0] ew = xp[R][56 +: 14];
                assign fi_v[28*gs + 8] = xv[R][4]; assign fi_we[28*gs + 8] = 1'b0;
                assign fi_row[14*(28*gs + 8) +: 14] = ew[0 +: 14]; assign fi_m[4*(28*gs + 8) +: 4] = 4'hf;
                if (gs == 0) begin : g_tag assign fi_d[128*(28*gs + 8) +: 128] = {124'd0, xp[R][473 +: 4]}; end
                else begin : g_ntag assign fi_d[128*(28*gs + 8) +: 128] = 128'd0; end
            end
            if (1) begin : g_p9
                wire [14:0] sw = s_cn[(6*gs + 5)*15 +: 15];
                assign xv[0][5] = sw[14]; assign xp[0][70 +: 14] = sw[13:0];
                wire [13:0] ew = xp[R][70 +: 14];
                assign fi_v[28*gs + 9] = xv[R][5]; assign fi_we[28*gs + 9] = 1'b0;
                assign fi_row[14*(28*gs + 9) +: 14] = ew[0 +: 14]; assign fi_m[4*(28*gs + 9) +: 4] = 4'hf;
                if (gs == 0) begin : g_tag assign fi_d[128*(28*gs + 9) +: 128] = {124'd0, xp[R][477 +: 4]}; end
                else begin : g_ntag assign fi_d[128*(28*gs + 9) +: 128] = 128'd0; end
            end
            if (1) begin : g_p10
                wire [142:0] sw = s_ld[(2*gs + 0)*143 +: 143];
                assign xv[0][6] = sw[142]; assign xp[0][84 +: 142] = sw[141:0];
                wire [141:0] ew = xp[R][84 +: 142];
                assign fi_v[28*gs + 10] = xv[R][6]; assign fi_we[28*gs + 10] = 1'b1;
                assign fi_row[14*(28*gs + 10) +: 14] = ew[128 +: 14]; assign fi_m[4*(28*gs + 10) +: 4] = 4'hf;
                assign fi_d[128*(28*gs + 10) +: 128] = ew[127:0];
            end
            if (1) begin : g_p11
                wire [142:0] sw = s_ld[(2*gs + 1)*143 +: 143];
                assign xv[0][7] = sw[142]; assign xp[0][226 +: 142] = sw[141:0];
                wire [141:0] ew = xp[R][226 +: 142];
                assign fi_v[28*gs + 11] = xv[R][7]; assign fi_we[28*gs + 11] = 1'b1;
                assign fi_row[14*(28*gs + 11) +: 14] = ew[128 +: 14]; assign fi_m[4*(28*gs + 11) +: 4] = 4'hf;
                assign fi_d[128*(28*gs + 11) +: 128] = ew[127:0];
            end
            assign xp[0][368] = rf_w[gs]; assign fi_rf[gs] = xp[R][368];
            if (gs == 0) begin : g_tg assign xp[0][369 +: 112] = x_cn; end else begin : g_ntg assign xp[0][369 +: 112] = 112'd0; end
            for (gr = 0; gr < R; gr = gr + 1) begin : g_r
                wire rni_x;
                if (gs == 0 && gr == 0) begin : g_a assign rni_x = src_rn[5]; end
                else if (gs == 0) begin : g_c assign rni_x = xr0[(4*5)*R + gr - 1]; end
                else begin : g_d assign rni_x = xr1[(4*5 + gs - 1)*R + gr]; end
                dsfd_vm_fxb u_r (.ck(ck), .rni(rni_x), .i_v(xv[gr]), .i(xp[gr]), .o_v(xv[gr+1]), .o(xp[gr+1]),
                    .rn_o({xr1[(4*5 + gs)*R + gr], xr0[(4*5 + gs)*R + gr]})
`ifdef OT_SPVM_RESET_ACK
                , .reset_epoch_n(rst[0]), .rst_ack(rst_ack[41+(4*5+gs)*R+gr])
`endif
                );
            end
        end
        // hard child, unchanged: pin flop + out flop; the constant fields and i_rf[2:0] are ties
        dsfd_vm_fsr_bank #(.BANK_XOR(BANK_XOR)) u_fr (.ck(ck[0]), .rn(xr0[(4*0 + gs)*R + R - 1]),
            .i_v(fi_v[28*gs +: 28]), .i_we(fi_we[28*gs +: 28]), .i_row(fi_row[392*gs +: 392]), .i_mask(fi_m[112*gs +: 112]),
            .i_d(fi_d[3584*gs +: 3584]), .i_rf({fi_rf[gs], 3'b000}),
            .o_v(m_v[28*gs +: 28]), .o_we(m_we[28*gs +: 28]), .o_row(m_row[392*gs +: 392]),
            .o_mask(m_mask[112*gs +: 112]), .o_d(m_d[3584*gs +: 3584]), .o_rf(m_rf[4*gs +: 4])
`ifdef OT_SPVM_RESET_ACK
                , .reset_epoch_n(rst[0]), .rst_ack(rst_ack[16+gs])
`endif
                );
    end endgenerate
endmodule
